  assert(hubLinks[0].label === TWENTY_FOURTH_HUB_LABEL, "twenty-fourth hub label is подборку музыки для сна");
  const soothingLinks = allLinks.filter((link) => link.href === TWENTY_FOURTH_SOOTHING_HREF);
